class Base<K, V> { m: Map<K, V> = new Map<K, V>(); }
class Child extends Base<string, number> {}
function main(): void {
  const m = new Map<string, number>([["a", 1], ["b", 2]]);
  const [first] = m;
  console.log(first);
  const st = new Set<number>([1, 2]);
  const [x, y] = st;
  console.log(x, y);
}
